var CONV_T = window.CONV_T || {}; CONV_T["zh"] = {"udca":["反向态度信号（挪威式：小牌鼓励）","同伴首攻时出小牌表示鼓励（继续该花色），大牌表示不鼓励——与标准相反。张数信号仍按标准：先大后小表示偶数张。"],"claudex":["Claude 加倍","Claude 体系（Bridge Table）。在部分定约争夺中，对对方二阶或三阶花色定约的加倍为惩罚性，条件是加倍者计算出至少宕二：他在对方将牌中的赢墩和旁门快速赢墩，加上同伴的份额（同伴每表示四点算一墩），对比对方可输的 7 − 阶数 墩。需要三张以上将牌。同伴放过，除非对方花色缺门且自己有长套。"],"twoOverOne":["2/1 逼局","未曾不叫的应叫人在同伴一阶开叫后于二阶叫新花色(1♣–2♦ 除外;1♠–2♥ 表示五张红心)为逼局,12+ 大牌点。1♥/1♠ 后应叫 1NT 逼叫一轮(6-12 点):开叫人没有其他叫品时叫三张低花;应叫人随后跳叫 3 阶高花表示三张支持的邀叫。已不叫过的一方二阶应叫不逼叫。"],"rkc":["RKCB 1430","4NT 问五张关键张(四张 A + 将牌 K)。5♣ = 1 或 4,5♦ = 3 或 0,5♥ = 2 张且无将牌 Q,5♠ = 2 张且有将牌 Q。"],"rkc0314":["RKCB 0314","4NT 问五张关键张(四张 A + 将牌 K)。5♣ = 0 或 3,5♦ = 1 或 4,5♥ = 2 张且无将牌 Q,5♠ = 2 张且有将牌 Q。取代 RKCB 1430。"],"gerber":["格伯","同伴叫 1NT、2NT 或 3NT 之后,未确定将牌时,4♣ 问 A。4♦ = 0 或 4,4♥ = 1,4♠ = 2,4NT = 3。问叫者可停在 4NT。"],"bergen":["伯根加叫","在 1♥/1♠ 后(不是在加倍或争叫之后):3♣ = 四张支持,7-9 点;3♦ = 四张支持,10-12(邀叫);3 阶高花 = 四张支持,0-6(阻击)。四张支持且 13+ 用雅可比 2NT 或爆裂叫。简单加叫表示三张支持,6-9;三张支持的邀叫经由逼叫性 1NT。"],"capp":["卡佩莱蒂","对方开叫 1NT 后(直接位置):X = 惩罚,15+ 点。2♣ = 单套(6+ 张):同伴叫 2♦ 询问,争叫者有方块就不叫,否则叫出花色。2♦ = 两高花(5-4 或更长):同伴选高花(跳叫为邀叫,10-12)。2♥/2♠ = 该高花 5+ 加一个 4+ 低花:同伴不叫、加叫或叫 2NT 询问低花。2NT = 两低花(5-5):同伴选择。"],"j2nt":["雅可比 2NT","高花开叫后应叫 2NT = 4+ 张支持,13+ 点,逼局。开叫人:3 阶新花 = 单张或缺门;4 阶新花 = 好的五张旁套;3 阶高花 = 18+ 无短门;3NT = 15-17 无短门;4 阶高花 = 低限。"],"wjs":["弱跳新花","应叫人在新花色上的单跳(如 1♦–2♠、1♣–2♥)表示 6+ 张套和弱牌(0-5 点)。这是止叫;开叫人不叫。对方加倍后不适用。"],"stayman":["斯台曼","1NT 后 2♣(2NT 后 3♣)问四张高花。回答:♦ = 无四张高花,♥ = 四张红心,♠ = 四张黑桃且没有四张红心。2♦ 之后 2♥/2♠ = 该高花五张 + 另一高花四张,邀叫。若应叫人在 2♥ 后叫 NT,有四张黑桃的开叫人也要叫出黑桃。"],"minorTr":["低花转移","1NT之后：2♠ → 草花（开叫人叫3♣），3♣ → 方块（开叫人叫3♦）。有六张低花的弱牌打3阶；2NT仍是自然邀叫。"],"fourWay":["四路转移","1NT 后:2♦ → 红心,2♥ → 黑桃(雅可比),2♠ → 梅花(开叫人叫 3♣),2NT → 方块(开叫人叫 3♦)。均型邀叫经由 2♣ 斯台曼。"],"puppet":["傀儡斯台曼","2NT 之后 3♣ 询问四张或五张高花（代替斯台曼）。回答：3♦ = 一门或两门四张高花，3♥ = 五张红心，3♠ = 五张黑桃，3NT = 没有四张高花。3♦ 之后应叫人叫出自己没有的高花：3♥ = 四张黑桃，3♠ = 四张红心，4♦ = 两门都有，3NT = 都没有；这样由开叫 2NT 的人做庄。"],"smolen":["斯莫伦","1NT–2♣–2♦ 之后,高花 5-4 的逼局牌在三阶叫出其四张高花:3♥ = 4♥ + 5♠,3♠ = 4♠ + 5♥,使强牌一方做庄。"],"michaels":["迈克尔斯扣叫 / 不寻常 2NT","直接扣叫对方的一阶开叫表示 5-5 两套,7+ 点:对低花开叫为两高花;对高花开叫为另一高花加一个低花(同伴叫 2NT 询问低花)。跳叫 2NT(不寻常)表示未叫过的两个最低花色。同伴选择花色;有配合且 10+ 可跳到成局。"],"splinter":["爆裂叫","高花开叫后在新花色上双跳(如 1♠–4♥、1♥–3♠)= 4+ 张支持,所叫花色单张或缺门,11-15 点,逼局,有满贯兴趣。开叫人停在 4 阶高花或探索满贯。"],"texas":["德州转移","1NT/2NT 后:4♦ → 4♥,4♥ → 4♠。6+ 张高花且有成局实力;由强牌一方(开叫人)做庄。"],"texasInt":["干扰后的德州","对方加倍我方 1NT 或在二、三阶争叫时德州转移仍然有效:4♦ → 红心,4♥ → 黑桃。叫对方的花色不是转移(对方 2♥ 争叫后,4♥ 是扣叫,4♦ 仍表示红心)。开叫人完成转移。"],"leb":["莱本索尔","我方 1NT 被二阶争叫后:2NT 迫使开叫人叫 3♣(用于停在某花色或慢速表示)。直接三阶花色为逼叫。直接 3NT 否认止张;先 2NT 再 3NT 表示有止张。扣叫对方花色为斯台曼:直接 = 无止张,经由 2NT = 有止张(“快则否认”)。"],"lav":["拉文索尔垫牌","防守信号。垫掉的花色是你不要的;大牌请求另外两门中较高的一门,小牌请求较低的一门(将牌和首攻花色不算)。同伴首攻时,大点子鼓励,最小的点子表示不鼓励。"],"roman":["罗马垫牌（奇偶）","防守信号。第一张垫牌：奇数牌（3、5、7、9）表示要这门花色；偶数牌（2、4、6、8、10）表示不要，并要另外两门中的一门：小偶数（2、4）要较低的，大偶数（6、8、10）要较高的（不算将牌和所出的花色）。同伴首攻时，较大的小牌表示鼓励，最小的表示不鼓励。"],"invMin":["反向低花加叫","未曾不叫的一方在 1♣/1♦ 后:加叫到 2 阶低花为强(10+ 点,4+ 张支持,梅花 5+,无四张高花)且逼叫一轮;开叫人均型低限叫 2NT,有余力就显示止张,低限则重复 3 阶低花。跳加到 3 阶为阻击(0-9 点,5+ 张支持)。"],"drury":["德鲁里","反向德鲁里。已不叫过的一方在同伴第三/第四家开叫 1♥/1♠ 后应叫 2♣ = 3+ 张支持且 10-12 点。开叫人轻开叫或低限时重复 2 阶高花(不成局),足额开叫叫 4 阶高花。"],"nmf":["新低花逼叫","1m–1M–1NT 之后,应叫人叫另一低花的 2 阶为人为逼叫(11+):询问开叫人是否对应叫人的高花有三张支持或另有四张高花。"],"fsf":["第四花色逼叫","我方已叫过三个花色时,应叫人叫第四花色为人为逼局;要求开叫人进一步描述(止张、支持或额外长度)。"],"ogust":["奥格斯特","同伴弱二开叫后,2NT 询问:3♣ = 低限,套差;3♦ = 低限,套好;3♥ = 高限,套差;3♠ = 高限,套好;3NT = 坚固套(AKQ)。"],"supx":["支持性加倍","1m–(不叫)–1M–(低于 2M 的争叫)之后,开叫人加倍表示对应叫人的高花恰好三张支持;直接加叫表示四张。"],"respx":["应答性加倍","对方开叫、同伴技术性加倍、对方加叫之后,加倍者同伴的加倍为技术性:8+ 点且持有两门未叫花色(通常是高花),没有明确叫品。"],"sjs":["强跳新花","应叫人在新花色上的单跳表示强牌(19+ 点),好套且有满贯兴趣。取代弱跳新花。"],"dont":["DONT","Disturb Opponents’ Notrump(马蒂·伯根)。对方 1NT 后:X = 单套(6+),同伴叫 2♣ 询问;2♣ = 梅花加一门更高花色;2♦ = 方块加一门高花;2♥ = 两高花;2♠ = 只有黑桃(自然)。同伴有容忍就不叫,否则叫下一门花色(不叫或改正)。取代卡佩莱蒂。"],"jtr":["雅可比转移","1NT 后 2♦ 要求开叫人叫红心,2♥ 要求叫黑桃,使强牌做庄。有四张支持且高限(17)时开叫人在三阶超接受。转移之后三阶新花色为自然且逼局。"],"sys":["体系叫品","所选体系的人为叫品(精确、波兰梅花、多义 2♦):它表示的内容写在上方。体系在首页(你的体系)或设置中选择。"],"bw":["黑木","4NT 问 A:5♣ = 0 或 4,5♦ = 1,5♥ = 2,5♠ = 3。"],"q":["定量 4NT","在无将叫品之后,4NT 不问 A,而是邀请满贯。同伴高限叫 6NT。"],"nego":["否定性加倍","同伴开叫、对方争叫后,加倍不是惩罚性的:表示未叫高花有四张且有足够叫牌实力。"],"takeout":["技术性加倍","对开叫的加倍:有开叫实力,对方花色短,其他花色有支持。同伴必须叫牌。"],"weak2":["弱二","开叫 2♦/2♥/2♠:好的六张套,5-10 点。阻击性开叫。"],"strong2c":["强 2♣","开叫 2♣:22+ 点或同等赢墩实力,人为且逼局。2♦ 为等待应叫。2♣–2♦–2♥/2♠ 之后 3♣ 为二次否定(0-3 点);2♣–2♦–2NT(22-24)按 2NT 开叫处理(斯台曼和转移)。"],"cue":["扣叫","叫对方的花色不是自然叫:表示对同伴有邀叫或更强的支持,为逼叫。"],"nt1":["1NT 开叫","15-17 点,均型。"],"pre":["阻击叫","三阶或四阶开叫:长套(7+)且牌力弱,压缩对方的叫牌空间。"],"runout":["1NT 被加倍后的逃叫","我方 1NT 被加倍时,弱牌应叫人逃到 5+ 张花色;再加倍表示有实力(9+)。"]};
var SYS_T = window.SYS_T || {}; SYS_T["zh"] = {"claude":"Claude 体系，由 Claude（Anthropic 的 AI）为 Bridge Table 设计：自然的基础——五张高花、较好低花 1♣/1♦、1NT 15-17、强 2♣、人为逼局 2♦、弱 2♥/2♠——以及在数千副牌双明手测量中选出的自有约定：Claude 加倍。","twoone":"五张高花,1NT 15-17,弱二,强 2♣。未不叫过的应叫人二阶新花逼局;高花开叫后 1NT 为逼叫。","sayc":"五张高花,1NT 15-17,弱二,强 2♣,雅可比转移与斯台曼,黑木。二阶新花逼叫一轮(10+);高花开叫后 1NT 为 6-10 且不逼叫;跳新花为强。","acol":"四张高花,弱 1NT(12-14),强 2♣(23+ 或逼局),♦ ♥ ♠ 弱二,限制性加叫(加叫保证四张),2NT 20-22,斯台曼和转移,RKCB。","sef":"Système d’Enseignement Français:五张高花,“较好低花”开 1♣/1♦,1NT 15-17,2♣ 强且逼叫,2♦ 人为逼局,2♥/2♠ 弱。二阶新花逼叫一轮;RKCB。","precision":"强梅花:1♣ = 16+ 任意牌型(人为,逼叫;1♦ = 否定 0-7)。其他开叫 11-15:1♦ 2+ ♦(兜底),1♥/1♠ 5+,1NT 13-15,2♣ 6+ ♣(或 5♣ + 四张高花),2♦ 方块短的三套(4-4-1-4 / 4-4-0-5),2♥/2♠ 弱。","polish":"Wspólny Język(波兰梅花):1♣ = (a) 12-14 均型,(b) 15+ 长梅花,或 (c) 18+ 任意(1♦ = 否定 0-7 或等待)。1♦ 4+ ♦ 非均型,1♥/1♠ 5+,1NT 15-17,2♣ 6+ ♣ 11-15,2♦ 多义(♥ 或 ♠ 弱二),2♥/2♠ 弱。"};
